#include <stdbool.h>

void bubble_sort(int a[], int n) {
    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
                swapped = true;
            }
        }
        if (!swapped) break;   /* no swap: already sorted */
    }
}

void bubble_sort_bound(int a[], int n) {
    int bound = n - 1;               /* last index still unsorted */
    while (bound > 0) {
        int last = 0;
        for (int j = 0; j < bound; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                last = j;            /* a[j+1..] is final */
            }
        }
        bound = last;
    }
}

void cocktail_sort(int a[], int n) {
    int lo = 0, hi = n - 1;
    bool swapped = true;
    while (swapped && lo < hi) {
        swapped = false;
        for (int j = lo; j < hi; j++)
            if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1];
                                   a[j + 1] = t; swapped = true; }
        hi--;
        for (int j = hi; j > lo; j--)
            if (a[j - 1] > a[j]) { int t = a[j]; a[j] = a[j - 1];
                                   a[j - 1] = t; swapped = true; }
        lo++;
    }
}

void bubble_sort_rec(int a[], int n) {
    if (n <= 1) return;
    bool swapped = false;
    for (int j = 0; j < n - 1; j++) {
        if (a[j] > a[j + 1]) {
            int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
            swapped = true;
        }
    }
    if (swapped) bubble_sort_rec(a, n - 1);   /* largest is now at a[n-1] */
}
